mapper.select:
select room.*, type.name as typeName, hotel.name as hotelName
from room
left join type on room.type_id = type.id and type.deleted = 0
left join hotel on room.hotel_id = hotel.id and hotel.deleted = 0

    room.deleted=0
     and room.id = #{id}
     and room.name like concat('%', #{name}, '%')
     and room.status = #{status}
     and room.type_id = #{typeId}
     and room.hotel_id = #{hotelId}


order by room.id desc

mapper.delete:
update room
set deleted = 1
where id = #{id}
